<script setup lang="ts">import {computed} from 'vue';import type {ResourcePlan,Task} from '../types/domain';import {num} from '../utils/format';const props=defineProps<{plan:ResourcePlan;tasks:Task[]}>();const rows=computed(()=>props.plan.baseline_schedule.tasks.slice().sort((a,b)=>a.start-b.start||a.task_id.localeCompare(b.task_id)));const finish=computed(()=>props.plan.baseline_schedule.project_finish);const disp=computed(()=>Object.fromEntries(props.plan.dispatch.map(d=>[d.task_id,d])));const name=(id:string)=>props.tasks.find(t=>t.task_id===id)?.name;const crews=(id:string)=>{const c=disp.value[id]?.crews;return c&&Object.keys(c).length?Object.entries(c).map(([k,v])=>k+'×'+v).join(' '):'—'};const X0=200,W=820;const x=(v:number)=>X0+(finish.value?v/finish.value:0)*W;const H=computed(()=>rows.value.length*26+58);</script><template><div class="gantt-scroll"><svg :viewBox="`0 0 1060 ${H}`" role="img" aria-label="班组受限基线派工甘特图"><g v-for="f in [0,.25,.5,.75,1]" :key="f"><line :x1="x(f*finish)" :x2="x(f*finish)" y1="10" :y2="H-26" stroke="#d7d1c3"/><text :x="x(f*finish)" :y="H-10" text-anchor="middle">{{num(f*finish,1)}}h</text></g><g v-for="(r,i) in rows" :key="r.task_id"><text class="node-id" x="12" :y="34+i*26+4">{{r.task_id}}</text><text class="node-name" x="52" :y="34+i*26+4">{{name(r.task_id)}} · P{{disp[r.task_id]?.priority}} · {{crews(r.task_id)}}</text><rect v-if="r.resource_wait>1e-8" class="gantt-wait" :x="x(r.precedence_ready)" :y="22+i*26" :width="Math.max(2,x(r.start)-x(r.precedence_ready))" height="16"><title>资源等待 {{num(r.precedence_ready)}}→{{num(r.start)}}h（{{num(r.resource_wait)}}h）</title></rect><rect class="gantt-work" :x="x(r.start)" :y="22+i*26" :width="Math.max(2,x(r.finish)-x(r.start))" height="16"><title>{{r.task_id}} 占用 {{num(r.start)}}→{{num(r.finish)}}h</title></rect></g></svg></div><div class="graph-legend"><span><i class="gantt-key work"/>占用施工（不抢占）</span><span><i class="gantt-key wait"/>资源等待：前置已就绪但班组被占用</span><span>派工顺序：优先级数值小者优先，并列按任务ID；先开工先占用</span></div><div class="table-scroll"><table><thead><tr><th>任务</th><th>优先级</th><th>占用班组</th><th>前置就绪 / h</th><th>开工 / h</th><th>完工 / h</th><th>资源等待 / h</th></tr></thead><tbody><tr v-for="r in rows" :key="r.task_id" :class="{critical:r.resource_wait>1e-8}"><td><b>{{r.task_id}}</b> {{name(r.task_id)}}</td><td>{{disp[r.task_id]?.priority}}</td><td>{{crews(r.task_id)}}</td><td>{{num(r.precedence_ready)}}</td><td>{{num(r.start)}}</td><td>{{num(r.finish)}}</td><td>{{num(r.resource_wait)}}</td></tr></tbody></table></div><p class="muted">最可能工期m下的班组受限基线：完工 {{num(finish)}}h（不计班组CPM对照见下表）。高亮行发生资源等待；容量随情景快照冻结。</p></template>